```java
import java.util.*;

class Transaction {
    private final int transactionId;
    private final int customerId;
    private final double amount;
    private final String status;

    public Transaction(int transactionId, int customerId, double amount, String status) {
        this.transactionId = transactionId;
        this.customerId = customerId;
        this.amount = amount;
        this.status = status;
    }

    public int getTransactionId() {
        return transactionId;
    }

    public int getCustomerId() {
        return customerId;
    }

    public double getAmount() {
        return amount;
    }

    public String getStatus() {
        return status;
    }
}


class CustomerRevenueService {

    /**
     * Calculates customer revenue summaries from a list of transactions.
     * @param transactions A list of transaction objects.
     * @return A map where keys are customer IDs and values are maps containing:
     *         - "totalRevenue": The total revenue generated by the customer.
     *         - "validTransactionsCount": The number of valid completed transactions for the customer.
     */
    public Map<Integer, Map<String, Integer>> calculateCustomerRevenue(List<Transaction> transactions) {
        Map<Integer, Map<String, Integer>> customerSummaries = new HashMap<>();

        for (Transaction transaction : transactions) {
            if ("COMPLETED".equalsIgnoreCase(transaction.getStatus())) {
                if (transaction.getCustomerId() != null && transaction.getAmount() > 0) {
                    int customerId = transaction.getCustomerId();
                    double amount = transaction.getAmount();

                    // Update customer summary
                    customerSummaries.computeIfAbsent(customerId, k -> new HashMap<>())
                            .put("totalRevenue", (customerSummaries.getOrDefault(customerId, new HashMap<>()).getOrDefault("totalRevenue", 0)) + amount);
                    customerSummaries.computeIfAbsent(customerId, k -> new HashMap<>()).put("validTransactionsCount", (customerSummaries.getOrDefault(customerId, new HashMap<>()).getOrDefault("validTransactionsCount", 0)) + 1);
                }
            }
        }

        // Sort by total revenue in descending order
        Map<Integer, Map<String, Integer>> sortedCustomerSummaries = new TreeMap<>(new RevenueComparator());

        sortedCustomerSummaries.putAll(customerSummaries); // Ensure all entries are present after sorting

        return sortedCustomerSummaries;
    }
}


class RevenueComparator implements Comparator<Map.Entry<Integer, Map<String, Integer>>> {
    @Override
    public int compare(Map.Entry<Integer, Map<String, Integer>> entry1, Map.Entry<Integer, Map<String, Integer>> entry2) {
        double revenue1 = entry1.getValue().getOrDefault("totalRevenue", 0.0);
        double revenue2 = entry2.getValue().getOrDefault("totalRevenue", 0.0);
        return Double.compare(revenue2, revenue1); // Descending order
    }
}


public class TransactionService {

    public static void main(String[] args) {
        // Example Usage:
        List<Transaction> transactions = new ArrayList<>();
        transactions.add(new Transaction(1, 101, 100.0, "COMPLETED"));
        transactions.add(new Transaction(2, 102, 50.0, "PENDING"));
        transactions.add(new Transaction(3, 101, 75.0, "COMPLETED"));
        transactions.add(new Transaction(4, 103, 25.0, "COMPLETED"));
        transactions.add(new Transaction(5, 102, 120.0, "COMPLETED"));
        transactions.add(new Transaction(6, 101, -10.0, "COMPLETED")); // Invalid amount
        transactions.add(new Transaction(7, null, 30.0, "COMPLETED")); // Null customer ID
        transactions.add(new Transaction(8, 104, 200.0, "COMPLETED"));

        CustomerRevenueService service = new CustomerRevenueService();
        Map<Integer, Map<String, Integer>> summaries = service.calculateCustomerRevenue(transactions);

        System.out.println("Customer Revenue Summaries (Sorted by Total Revenue):");
        for (Map.Entry<Integer, Map<String, Integer>> entry : summaries.entrySet()) {
            System.out.print("Customer ID: " + entry.getKey() + ", ");
            System.out.println("Total Revenue: " + entry.getValue().get("totalRevenue") + ", Valid Transactions: " + entry.getValue().get("validTransactionsCount"));
        }
    }
}
```

